pub fn platform_upsert(db orm.Connection) ! {
	for item in pf_product() {
		sql db {
			upsert item into schema_platform.PfProduct
		} or { return err }
	}
	for item in pf_portal() {
		sql db {
			upsert item into schema_platform.PfPortal
		} or { return err }
	}
	for item in pf_menu() {
		sql db {
			upsert item into schema_platform.PfMenu
		} or { return err }
	}
	for item in pf_api() {
		sql db {
			upsert item into schema_platform.PfApi
		} or { return err }
	}
}

